sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float angle;
uniform float reach;
layout(color) uniform half4 color;
uniform float alpha;
uniform float fade;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    float a = radians(angle);
    float2 d = float2(cos(a), sin(a)) * reach;
    float shade = 0.0;
    for (int i = 1; i <= 64; i++) {
        float t = float(i) / 64.0;
        float hit = float(image.eval(coord - d * t).a) * (1.0 - fade * t);
        shade = max(shade, hit);
    }
    float sa = shade * clamp(alpha, 0.0, 1.0) * float(color.a);
    half4 s = half4(half3(color.rgb) * half(sa), half(sa));
    return src + s * (1.0 - src.a);
}
